import { expect, test } from 'bun:test';
import { createHash } from 'node:crypto';

const checker = await import('./check-domain-contracts');

test('rejects source-only drift even when generated content integrity remains valid', () => {
  const sourceHashInArtifact = 'a'.repeat(64);
  const currentSourceHash = 'b'.repeat(64);
  const body = 'export const PARTICIPATION_STATUSES = {};\nexport const COLLECTION_MODULE_IDS = {};\n';
  const contentHash = createHash('sha256').update(body, 'utf-8').digest('hex');
  const generated = [
    '// Generated by scripts/generate-chronicle-contracts.py from ontology/chronicle.linkml.yaml.',
    `// Source-SHA256: ${sourceHashInArtifact}`,
    `// Content-SHA256: ${contentHash}`,
    '// Do not edit by hand.',
    body,
  ].join('\n');
  const path = 'synthetic/chronicle-contracts.ts';
  const errors = checker.verifyGeneratedModule(
    path,
    generated,
    {
      provenance: /^\/\/ Generated by scripts\/generate-chronicle-contracts\.py from ontology\/chronicle\.linkml\.yaml\./m,
      requiredExports: ['PARTICIPATION_STATUSES', 'COLLECTION_MODULE_IDS'],
    },
    currentSourceHash,
  );

  expect(errors).toContain(
    `${path}: Source-SHA256 mismatch: generated artifact uses ${sourceHashInArtifact}, current sources hash to ${currentSourceHash}`,
  );
});
